const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const greatLakes = ee.Geometry.Polygon([
    [-92.5, 49.0], [-75.5, 49.0], [-75.5, 41.0], [-92.5, 41.0], [-92.5, 49.0]
  ]);

  const date1 = '2021-02-20';
  const date2 = '2021-03-03';

  // 2. Data Acquisition - MODIS Snow Cover
  const modisCol = ee.ImageCollection('MODIS/061/MOD10A1')
    .filterBounds(greatLakes)
    .select('NDSI_Snow_Cover');

  const img1 = modisCol.filterDate(date1, ee.Date(date1).advance(1, 'day')).first();
  const img2 = modisCol.filterDate(date2, ee.Date(date2).advance(1, 'day')).first();

  // Check if images exist
  const img1Exists = img1 ? true : false;
  const img2Exists = img2 ? true : false;

  if (!img1Exists || !img2Exists) {
    console.log(`Feb 20 image: ${img1Exists ? 'Found' : 'Missing'}`);
    console.log(`Mar 3 image: ${img2Exists ? 'Found' : 'Missing'}`);
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate ice coverage (NDSI > 0 over water)
  const waterMask = ee.Image('JRC/GSW1_4/GlobalSurfaceWater').select('occurrence').gt(0);

  const getIceCoverage = function(img) {
    const iceMask = img.gt(0); // NDSI > 0 indicates snow/ice
    const waterIce = iceMask.updateMask(waterMask);
    return waterIce.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: greatLakes,
      scale: 1000,
      maxPixels: 1e9
    }).get('NDSI_Snow_Cover');
  };

  const ice1 = await getIceCoverage(img1).getInfo();
  const ice2 = await getIceCoverage(img2).getInfo();

  // 4. Check for valid pixels
  if (ice1 === null || ice2 === null || ice1 === 0 || ice2 === 0) {
    console.log(`Ice coverage - Feb 20: ${ice1}, Mar 3: ${ice2}`);
    console.log("<answer>C2</answer>");
    return;
  }

  // 5. Validation & Final Answer
  console.log(`Ice coverage - Feb 20: ${ice1}, Mar 3: ${ice2}`);

  if (ice1 === null || ice2 === null || isNaN(ice1) || isNaN(ice2)) {
    console.log("<answer>C3</answer>");
  } else if (ice1 > ice2) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
